mapper.select:
SELECT id, rule_code, name, category, sub_category, protocol, port, banner_regex,
       vendor, product, version_expr, confidence, description, enabled, priority, created_at, updated_at
FROM asset_fingerprint_rule
WHERE 1 = 1

      AND (
          rule_code LIKE CONCAT('%', #{keyword}, '%')
          OR name LIKE CONCAT('%', #{keyword}, '%')
          OR product LIKE CONCAT('%', #{keyword}, '%')
          OR sub_category LIKE CONCAT('%', #{keyword}, '%')
          OR banner_regex LIKE CONCAT('%', #{keyword}, '%')
      )


      AND category = #{category}


      AND port = #{port}


      AND enabled = #{enabled}

ORDER BY priority ASC, id ASC
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(1)
FROM asset_fingerprint_rule
WHERE 1 = 1

      AND (
          rule_code LIKE CONCAT('%', #{keyword}, '%')
          OR name LIKE CONCAT('%', #{keyword}, '%')
          OR product LIKE CONCAT('%', #{keyword}, '%')
          OR sub_category LIKE CONCAT('%', #{keyword}, '%')
          OR banner_regex LIKE CONCAT('%', #{keyword}, '%')
      )


      AND category = #{category}


      AND port = #{port}


      AND enabled = #{enabled}
